-- ===== 20261107000100_init.sql =====

-- ============================================================================
-- Third Place — core schema
-- ============================================================================
-- Columns marked "beyond spec" were added because a screen needs them; they are
-- called out so you can drop them if you'd rather compute the value elsewhere.

create extension if not exists pgcrypto with schema extensions;

create schema if not exists app_private;
comment on schema app_private is
  'Internal views/functions that read across all users. NEVER granted to anon or
   authenticated — the public aggregate views in 0300 are the only way out.';

-- ---------------------------------------------------------------- enums ------
do $$ begin
  create type public.venue_type    as enum ('cafe', 'study', 'other');
exception when duplicate_object then null; end $$;

do $$ begin
  create type public.table_status  as enum ('open', 'taken');
exception when duplicate_object then null; end $$;

do $$ begin
  create type public.reward_type   as enum ('frequent', 'passport');
exception when duplicate_object then null; end $$;

do $$ begin
  create type public.reward_status as enum ('in_progress', 'earned', 'redeemed');
exception when duplicate_object then null; end $$;

-- ------------------------------------------------------------ constants ------
-- A check-in is considered over after this long, even if nobody tapped
-- "check out". Referenced by the aggregate views and auto_checkout_stale().
create or replace function public.session_length()
returns interval language sql immutable parallel safe as $$
  select interval '3 hours';
$$;

-- Calgary. Used for "busiest hours" and the weekday on a familiar-faces card.
create or replace function public.local_tz()
returns text language sql immutable parallel safe as $$
  select 'America/Edmonton';
$$;

-- ---------------------------------------------------------------- users ------
create table if not exists public.users (
  id                    uuid primary key references auth.users (id) on delete cascade,
  name                  text        not null default '',
  interests             text[]      not null default '{}',
  vibe_tags             text[]      not null default '{}',
  incognito             boolean     not null default false,
  familiar_faces_opt_in boolean     not null default true,
  created_at            timestamptz not null default now()
);

comment on column public.users.incognito is
  'When true the user is excluded from every aggregate and from familiar faces.';

-- Keep public.users in step with auth.users on sign-up.
create or replace function public.handle_new_user()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  insert into public.users (id, name)
  values (
    new.id,
    coalesce(
      nullif(new.raw_user_meta_data ->> 'name', ''),
      nullif(new.raw_user_meta_data ->> 'full_name', ''),
      ''
    )
  )
  on conflict (id) do nothing;
  return new;
end $$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- --------------------------------------------------------------- venues ------
create table if not exists public.venues (
  id              uuid primary key default gen_random_uuid(),
  name            text              not null,
  lat             double precision  not null check (lat between -90 and 90),
  lng             double precision  not null check (lng between -180 and 180),
  type            public.venue_type not null default 'cafe',
  address         text,
  insider_info    text,
  popular_drinks  text[]            not null default '{}',
  vibe_summary    text,
  -- beyond spec: backs the "quiet" and "good for groups" map filter chips.
  is_quiet        boolean           not null default false,
  good_for_groups boolean           not null default false,
  created_at      timestamptz       not null default now()
);

create index if not exists venues_location_idx on public.venues (lat, lng);

-- --------------------------------------------------------------- tables ------
create table if not exists public.tables (
  id            uuid primary key default gen_random_uuid(),
  venue_id      uuid                not null references public.venues (id) on delete cascade,
  label         text                not null,
  seats         smallint            not null default 2 check (seats between 1 and 20),
  status        public.table_status not null default 'open',
  is_chat_table boolean             not null default false,
  updated_at    timestamptz         not null default now(),
  unique (venue_id, label)
);

-- Exactly one chat table per venue (at most one; a venue may have none).
create unique index if not exists tables_one_chat_table_per_venue
  on public.tables (venue_id) where is_chat_table;

create index if not exists tables_venue_idx on public.tables (venue_id);

create or replace function public.touch_updated_at()
returns trigger language plpgsql as $$
begin
  new.updated_at := now();
  return new;
end $$;

drop trigger if exists tables_touch_updated_at on public.tables;
create trigger tables_touch_updated_at
  before update on public.tables
  for each row execute function public.touch_updated_at();

-- ------------------------------------------------------------- checkins ------
create table if not exists public.checkins (
  id             uuid primary key default gen_random_uuid(),
  user_id        uuid        not null references public.users (id)  on delete cascade,
  venue_id       uuid        not null references public.venues (id) on delete cascade,
  table_id       uuid                 references public.tables (id) on delete set null,
  open_to_chat   boolean     not null default false,
  checked_in_at  timestamptz not null default now(),
  checked_out_at timestamptz,
  constraint checkins_checkout_after_checkin
    check (checked_out_at is null or checked_out_at >= checked_in_at)
);

-- One live session per person. Enforces the "check out of the old table first"
-- behaviour in public.check_in().
create unique index if not exists checkins_one_open_per_user
  on public.checkins (user_id) where checked_out_at is null;

create index if not exists checkins_venue_time_idx  on public.checkins (venue_id, checked_in_at desc);
create index if not exists checkins_user_time_idx    on public.checkins (user_id, checked_in_at desc);
create index if not exists checkins_open_idx         on public.checkins (venue_id) where checked_out_at is null;

-- ---------------------------------------------------------- kiosk_codes ------
create table if not exists public.kiosk_codes (
  id         uuid primary key default gen_random_uuid(),
  venue_id   uuid        not null references public.venues (id) on delete cascade,
  code       text        not null unique,
  expires_at timestamptz not null,
  created_at timestamptz not null default now()
);

create index if not exists kiosk_codes_venue_idx on public.kiosk_codes (venue_id, expires_at desc);

-- ------------------------------------------------------- familiar_faces ------
create table if not exists public.familiar_faces (
  id              uuid primary key default gen_random_uuid(),
  user_a          uuid        not null references public.users (id)  on delete cascade,
  user_b          uuid        not null references public.users (id)  on delete cascade,
  venue_id        uuid        not null references public.venues (id) on delete cascade,
  overlap_count   integer     not null default 0,
  a_accepted      boolean     not null default false,
  b_accepted      boolean     not null default false,
  -- beyond spec: the card copy says "...keep crossing paths at X on [day]",
  -- so the matcher records which weekday the overlaps cluster on.
  common_weekday  smallint             check (common_weekday between 0 and 6),
  last_overlap_at timestamptz,
  created_at      timestamptz not null default now(),
  -- user_a < user_b keeps a pair from being stored twice.
  constraint familiar_faces_ordered check (user_a < user_b),
  unique (user_a, user_b, venue_id)
);

comment on column public.familiar_faces.common_weekday is
  '0 = Sunday .. 6 = Saturday, matching Postgres extract(dow).';

create index if not exists familiar_faces_user_a_idx on public.familiar_faces (user_a);
create index if not exists familiar_faces_user_b_idx on public.familiar_faces (user_b);

-- -------------------------------------------------------------- rewards ------
create table if not exists public.rewards (
  id       uuid primary key default gen_random_uuid(),
  user_id  uuid                 not null references public.users (id)  on delete cascade,
  venue_id uuid                          references public.venues (id) on delete cascade,
  type     public.reward_type   not null,
  progress integer              not null default 0 check (progress >= 0),
  status   public.reward_status not null default 'in_progress'
);

comment on column public.rewards.venue_id is
  'Set for type = frequent (progress toward that one cafe). NULL for type =
   passport (progress is the number of distinct venues visited).';

-- venue_id is nullable, so coalesce it to make the uniqueness enforceable.
create unique index if not exists rewards_one_per_user_scope
  on public.rewards (
    user_id,
    type,
    coalesce(venue_id, '00000000-0000-0000-0000-000000000000'::uuid)
  );

create index if not exists rewards_user_idx on public.rewards (user_id);

-- ===== 20261107000200_rls.sql =====

-- ============================================================================
-- Third Place — row level security
-- ============================================================================
-- The privacy rules from the brief, expressed as policies:
--
--   * Nobody can read another person's row in users or checkins. That is what
--     makes "never display which specific users are at a venue" true at the
--     database level rather than only in the UI.
--   * Crowd information leaves the database only through the aggregate views
--     and functions in 0300, which run with the definer's rights and emit
--     counts, never user ids.
--   * Names are revealed only by public.my_familiar_faces(), and only once
--     both people have accepted.

alter table public.users         enable row level security;
alter table public.venues        enable row level security;
alter table public.tables        enable row level security;
alter table public.checkins      enable row level security;
alter table public.kiosk_codes   enable row level security;
alter table public.familiar_faces enable row level security;
alter table public.rewards       enable row level security;

-- ---------------------------------------------------------------- users ------
drop policy if exists users_select_self on public.users;
create policy users_select_self on public.users
  for select to authenticated
  using (id = auth.uid());

drop policy if exists users_insert_self on public.users;
create policy users_insert_self on public.users
  for insert to authenticated
  with check (id = auth.uid());

drop policy if exists users_update_self on public.users;
create policy users_update_self on public.users
  for update to authenticated
  using (id = auth.uid())
  with check (id = auth.uid());

-- No delete policy: account deletion goes through auth.users and cascades.

-- --------------------------------------------------------------- venues ------
-- Venue detail is public information; anon can read it so the map works before
-- sign-in. Writes are left to the service role (seed script / admin tooling).
drop policy if exists venues_select_all on public.venues;
create policy venues_select_all on public.venues
  for select to anon, authenticated
  using (true);

-- --------------------------------------------------------------- tables ------
-- Table status is public: it is the thing painted on the map and the kiosk.
-- It says "table 4 is taken", never who is sitting there.
drop policy if exists tables_select_all on public.tables;
create policy tables_select_all on public.tables
  for select to anon, authenticated
  using (true);

-- TODO(auth): gate this on a staff role before this is used outside a demo.
-- Right now any signed-in account can flip a table on the kiosk grid, which is
-- what lets the tablet work without a second auth system. A real deployment
-- wants a venue_staff table and `using (exists (select 1 from venue_staff ...))`.
drop policy if exists tables_staff_update_status on public.tables;
create policy tables_staff_update_status on public.tables
  for update to authenticated
  using (true)
  with check (true);

-- ------------------------------------------------------------- checkins ------
-- Own rows only, read and write. Everything a client needs about *other*
-- people's check-ins comes back as a count from an aggregate view.
drop policy if exists checkins_select_own on public.checkins;
create policy checkins_select_own on public.checkins
  for select to authenticated
  using (user_id = auth.uid());

drop policy if exists checkins_insert_own on public.checkins;
create policy checkins_insert_own on public.checkins
  for insert to authenticated
  with check (user_id = auth.uid());

drop policy if exists checkins_update_own on public.checkins;
create policy checkins_update_own on public.checkins
  for update to authenticated
  using (user_id = auth.uid())
  with check (user_id = auth.uid());

-- ---------------------------------------------------------- kiosk_codes ------
-- Deliberately no select policy for anon or authenticated. If clients could
-- read this table, anyone could check in to any cafe from home by reading the
-- current code. Codes are minted by public.rotate_kiosk_code() and validated
-- inside public.check_in(); both are security definer.

-- ------------------------------------------------------- familiar_faces ------
-- A user can see a pair they are part of. The row contains the other person's
-- user id, so the client should read these through public.my_familiar_faces(),
-- which strips the id and only exposes a first name after mutual acceptance.
-- This policy exists so realtime and ad-hoc queries still behave.
drop policy if exists familiar_faces_select_own on public.familiar_faces;
create policy familiar_faces_select_own on public.familiar_faces
  for select to authenticated
  using (auth.uid() in (user_a, user_b));

-- Accept/ignore goes through public.respond_to_familiar_face(), which makes
-- sure you can only ever flip your own side of the pair.
drop policy if exists familiar_faces_update_own_side on public.familiar_faces;
create policy familiar_faces_update_own_side on public.familiar_faces
  for update to authenticated
  using (auth.uid() in (user_a, user_b))
  with check (auth.uid() in (user_a, user_b));

-- -------------------------------------------------------------- rewards ------
drop policy if exists rewards_select_own on public.rewards;
create policy rewards_select_own on public.rewards
  for select to authenticated
  using (user_id = auth.uid());

drop policy if exists rewards_write_own on public.rewards;
create policy rewards_write_own on public.rewards
  for all to authenticated
  using (user_id = auth.uid())
  with check (user_id = auth.uid());

-- --------------------------------------------- lock down app_private --------
revoke all on schema app_private from anon, authenticated;

-- ===== 20261107000300_aggregates.sql =====

-- ============================================================================
-- Third Place — the aggregate layer
-- ============================================================================
-- Everything a client learns about other people comes from this file.
--
-- The views in app_private read across all users (they are owned by the
-- migration role, so they are not subject to RLS) and are never granted to
-- anon or authenticated. The views in public are built on top of them and emit
-- counts only -- no user ids, no names, no "who is here right now".
--
-- Incognito users are filtered out in app_private, once, so no caller can
-- forget to do it.

-- ------------------------------------------------- internal base views ------
-- Live sessions: not checked out, and not older than session_length().
create or replace view app_private.active_checkins as
  select c.*
  from public.checkins c
  join public.users u on u.id = c.user_id
  where c.checked_out_at is null
    and c.checked_in_at > now() - public.session_length()
    and u.incognito = false;

-- Historical sessions that are allowed to feed stats.
create or replace view app_private.countable_checkins as
  select c.*
  from public.checkins c
  join public.users u on u.id = c.user_id
  where u.incognito = false;

revoke all on app_private.active_checkins    from anon, authenticated;
revoke all on app_private.countable_checkins from anon, authenticated;

-- ---------------------------------------------------- live venue status ------
-- Drives the map markers, the bottom-sheet preview and the venue screen.
create or replace view public.venue_live as
with t as (
  select
    venue_id,
    count(*)::int                                             as total_tables,
    count(*) filter (where status = 'open')::int               as open_tables,
    count(*) filter (where is_chat_table)::int                 as chat_tables,
    count(*) filter (where is_chat_table and status = 'open')::int as chat_tables_open
  from public.tables
  group by venue_id
),
c as (
  select
    ac.venue_id,
    count(*) filter (where ac.open_to_chat)::int as people_open_to_chat,
    count(*) filter (where tb.is_chat_table)::int as people_at_chat_table
  from app_private.active_checkins ac
  left join public.tables tb on tb.id = ac.table_id
  group by ac.venue_id
)
select
  v.id                                            as venue_id,
  coalesce(t.total_tables, 0)                     as total_tables,
  coalesce(t.open_tables, 0)                      as open_tables,
  coalesce(t.chat_tables, 0) > 0                  as has_chat_table,
  coalesce(t.chat_tables_open, 0) > 0             as chat_table_open,
  coalesce(c.people_open_to_chat, 0)              as people_open_to_chat,
  -- "the chat table is active" means somebody is actually sitting at it.
  coalesce(c.people_at_chat_table, 0) > 0         as chat_table_active,
  case
    when coalesce(t.total_tables, 0) = 0                                 then 'open'
    when coalesce(t.open_tables, 0) = 0                                  then 'full'
    when t.open_tables::numeric / t.total_tables <= 0.34                  then 'filling_up'
    else 'open'
  end                                             as availability
from public.venues v
left join t on t.venue_id = v.id
left join c on c.venue_id = v.id;

comment on view public.venue_live is
  'Per-venue live counts. Safe to expose: contains no user ids and no names.';

-- ------------------------------------------------------- busiest hours ------
create or replace view public.venue_busy_hours as
select
  cc.venue_id,
  extract(hour from cc.checked_in_at at time zone public.local_tz())::int as hour_of_day,
  count(*)::int as visits
from app_private.countable_checkins cc
where cc.checked_in_at > now() - interval '60 days'
group by 1, 2;

comment on view public.venue_busy_hours is
  'Check-in counts by local hour over the last 60 days. Aggregate only.';

-- ---------------------------------------------------------- crowd type ------
-- "Crowd type, aggregated only": the vibe tags of people who have been here
-- recently. The having clause is the privacy guard -- a tag held by one or two
-- people would describe an individual, so it is not published at all.
create or replace view public.venue_crowd_tags as
select
  cc.venue_id,
  tag,
  count(distinct cc.user_id)::int as people
from app_private.countable_checkins cc
join public.users u on u.id = cc.user_id
cross join unnest(u.vibe_tags) as tag
where cc.checked_in_at > now() - interval '30 days'
group by 1, 2
having count(distinct cc.user_id) >= 3;

comment on view public.venue_crowd_tags is
  'Vibe tags held by at least 3 distinct recent visitors. Below 3 the tag is
   suppressed so it cannot describe one identifiable person.';

grant select on public.venue_live       to anon, authenticated;
grant select on public.venue_busy_hours to anon, authenticated;
grant select on public.venue_crowd_tags to anon, authenticated;

-- ----------------------------------------------------- owner dashboard ------
-- Minimum group size for anything on the cafe owner dashboard.
create or replace function public.dashboard_min_group_size()
returns integer language sql immutable parallel safe as $$ select 5; $$;

create or replace function public.venue_dashboard(p_venue_id uuid, p_days integer default 30)
returns jsonb
language plpgsql
security definer
set search_path = public, app_private
stable
as $$
declare
  v_min        integer := public.dashboard_min_group_size();
  v_visitors   integer;
  v_result     jsonb;
begin
  if auth.uid() is null then
    raise exception 'You must be signed in to view a venue dashboard.';
  end if;

  -- TODO(auth): restrict this to the owner of p_venue_id once there is a
  -- venue_staff / venue_owners table. Today any signed-in account can open the
  -- dashboard for any venue. It only ever returns aggregates, so this is a
  -- demo-grade gap rather than a leak of individual data.

  select count(distinct user_id) into v_visitors
  from app_private.countable_checkins
  where venue_id = p_venue_id
    and checked_in_at > now() - make_interval(days => p_days);

  -- Privacy rule: no aggregate below the minimum group size, at all.
  if coalesce(v_visitors, 0) < v_min then
    return jsonb_build_object(
      'suppressed',      true,
      'min_group_size',  v_min,
      'days',            p_days
    );
  end if;

  select jsonb_build_object(
    'suppressed',     false,
    'min_group_size', v_min,
    'days',           p_days,
    'visitors',       v_visitors,
    'total_visits',   (
      select count(*)::int from app_private.countable_checkins
      where venue_id = p_venue_id and checked_in_at > now() - make_interval(days => p_days)
    ),
    -- share of visitors who came more than once in the window
    'repeat_visit_rate', (
      select round(
        coalesce(
          count(*) filter (where visits > 1)::numeric / nullif(count(*), 0),
          0
        ), 3)
      from (
        select user_id, count(*) as visits
        from app_private.countable_checkins
        where venue_id = p_venue_id and checked_in_at > now() - make_interval(days => p_days)
        group by user_id
      ) per_user
    ),
    'chat_table_visits', (
      select count(*)::int
      from app_private.countable_checkins cc
      join public.tables t on t.id = cc.table_id
      where cc.venue_id = p_venue_id
        and cc.checked_in_at > now() - make_interval(days => p_days)
        and t.is_chat_table
    ),
    'open_to_chat_visits', (
      select count(*)::int
      from app_private.countable_checkins
      where venue_id = p_venue_id
        and checked_in_at > now() - make_interval(days => p_days)
        and open_to_chat
    ),
    'peak_hours', (
      select coalesce(jsonb_agg(jsonb_build_object('hour', hour_of_day, 'visits', visits)
                                order by hour_of_day), '[]'::jsonb)
      from (
        select extract(hour from checked_in_at at time zone public.local_tz())::int as hour_of_day,
               count(*)::int as visits
        from app_private.countable_checkins
        where venue_id = p_venue_id and checked_in_at > now() - make_interval(days => p_days)
        group by 1
      ) h
    )
  ) into v_result;

  return v_result;
end $$;

comment on function public.venue_dashboard(uuid, integer) is
  'Cafe owner dashboard. Returns {suppressed: true} rather than any number when
   fewer than dashboard_min_group_size() distinct people visited in the window.';

revoke all on function public.venue_dashboard(uuid, integer) from public;
grant execute on function public.venue_dashboard(uuid, integer) to authenticated;

-- ===== 20261107000400_rpc.sql =====

-- ============================================================================
-- Third Place — RPCs
-- ============================================================================
-- ERROR CONVENTION
-- Every user-facing failure is a plain `raise exception` (SQLSTATE P0001),
-- which PostgREST returns as HTTP 400 with the message intact, so the message
-- is safe to show directly in the UI. A stable token goes in `hint` for code
-- that needs to branch on the reason:
--   kiosk_code_invalid | table_not_at_venue | table_taken | familiar_face_not_found
-- See CHECKIN_ERROR_HINTS in src/lib/checkins.ts.
--
-- These are security definer on purpose. They are the only code that reads
-- kiosk_codes, the only code that writes a check-in alongside a table status,
-- and the only code that can ever return another person's name.

-- -------------------------------------------------------- kiosk rotation ----
-- The kiosk screen calls this every KIOSK_ROTATE_SECONDS. The code lives a
-- little longer than the rotation interval so a scan that lands mid-rotation
-- still validates.
create or replace function public.rotate_kiosk_code(
  p_venue_id    uuid,
  p_ttl_seconds integer default 60
)
returns jsonb
language plpgsql
security definer
set search_path = public, extensions
as $$
declare
  v_code    text;
  v_expires timestamptz;
begin
  if auth.uid() is null then
    raise exception 'You must be signed in to run kiosk mode.';
  end if;

  -- TODO(auth): gate on a staff role for p_venue_id. See the matching TODO on
  -- the tables update policy in 0200.

  if p_ttl_seconds < 10 or p_ttl_seconds > 600 then
    raise exception 'p_ttl_seconds must be between 10 and 600.';
  end if;

  -- 8 hex characters: short enough to re-type by hand if the camera fails,
  -- large enough (4 billion) that guessing within a 60 second window is hopeless.
  v_code    := upper(encode(extensions.gen_random_bytes(4), 'hex'));
  v_expires := now() + make_interval(secs => p_ttl_seconds);

  -- Housekeeping so the table does not grow without bound.
  delete from public.kiosk_codes
  where venue_id = p_venue_id and expires_at < now() - interval '10 minutes';

  insert into public.kiosk_codes (venue_id, code, expires_at)
  values (p_venue_id, v_code, v_expires);

  return jsonb_build_object('code', v_code, 'expires_at', v_expires);
end $$;

revoke all on function public.rotate_kiosk_code(uuid, integer) from public;
grant execute on function public.rotate_kiosk_code(uuid, integer) to authenticated;

-- ------------------------------------------------------------- check in -----
create or replace function public.check_in(
  p_code         text,
  p_table_id     uuid,
  p_open_to_chat boolean default false
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user    uuid := auth.uid();
  v_venue   uuid;
  v_is_chat boolean;
  v_status  public.table_status;
  v_checkin public.checkins;
begin
  if v_user is null then
    raise exception 'You must be signed in to check in.';
  end if;

  -- 1. The code must exist and must not have expired.
  select venue_id into v_venue
  from public.kiosk_codes
  where code = upper(trim(p_code))
    and expires_at > now();

  if v_venue is null then
    raise exception 'That code has expired. Grab a fresh one from the kiosk.'
      using hint = 'kiosk_code_invalid';
  end if;

  -- 2. The table has to belong to the venue that code was minted for, so a
  --    valid code for cafe A cannot be used to claim a table at cafe B.
  select is_chat_table, status into v_is_chat, v_status
  from public.tables
  where id = p_table_id and venue_id = v_venue
  for update;

  if not found then
    raise exception 'That table is not at this venue.'
      using hint = 'table_not_at_venue';
  end if;

  if v_status = 'taken' then
    raise exception 'Someone just took that table. Pick another one.'
      using hint = 'table_taken';
  end if;

  -- 3. Close any session still open for this person and free the table they
  --    were sitting at. checkins_one_open_per_user depends on this.
  with closed as (
    update public.checkins
       set checked_out_at = now()
     where user_id = v_user and checked_out_at is null
    returning table_id
  )
  update public.tables t
     set status = 'open'
   where t.id in (select table_id from closed where table_id is not null);

  -- 4. Sitting at the chat table *is* opting in to chat.
  insert into public.checkins (user_id, venue_id, table_id, open_to_chat)
  values (v_user, v_venue, p_table_id, p_open_to_chat or v_is_chat)
  returning * into v_checkin;

  update public.tables set status = 'taken' where id = p_table_id;

  -- TODO(rewards): recompute this user's rewards here.
  --   perform public.recompute_rewards(v_user);
  -- Chat-table check-ins count double -- see 0500.

  -- TODO(familiar-faces): either call the matcher for this user now, or leave
  -- it entirely to the scheduled job in 0500. Doing it here makes the demo
  -- feel instant; doing it on a schedule is cheaper.
  --   perform app_private.refresh_familiar_faces_for_venue(v_venue);

  return to_jsonb(v_checkin) || jsonb_build_object('venue_id', v_venue, 'at_chat_table', v_is_chat);
end $$;

revoke all on function public.check_in(text, uuid, boolean) from public;
grant execute on function public.check_in(text, uuid, boolean) to authenticated;

-- ------------------------------------------------------------ check out -----
create or replace function public.check_out()
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user  uuid := auth.uid();
  v_table uuid;
  v_id    uuid;
begin
  if v_user is null then
    raise exception 'You must be signed in to check out.';
  end if;

  update public.checkins
     set checked_out_at = now()
   where user_id = v_user and checked_out_at is null
  returning id, table_id into v_id, v_table;

  if v_id is null then
    return jsonb_build_object('checked_out', false);
  end if;

  if v_table is not null then
    update public.tables set status = 'open' where id = v_table;
  end if;

  return jsonb_build_object('checked_out', true, 'checkin_id', v_id);
end $$;

revoke all on function public.check_out() from public;
grant execute on function public.check_out() to authenticated;

-- ------------------------------------------------- automatic check out ------
-- "Auto check-out after 3 hours". The aggregate views already ignore sessions
-- older than session_length(), so the counts are correct even if this never
-- runs; this is what actually frees the table and closes the row.
create or replace function public.auto_checkout_stale()
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_count integer;
begin
  with closed as (
    update public.checkins
       set checked_out_at = checked_in_at + public.session_length()
     where checked_out_at is null
       and checked_in_at < now() - public.session_length()
    returning id, table_id
  ),
  freed as (
    update public.tables t
       set status = 'open'
     where t.id in (select table_id from closed where table_id is not null)
    returning t.id
  )
  select count(*)::int into v_count from closed;

  return v_count;
end $$;

comment on function public.auto_checkout_stale() is
  'Closes check-ins older than session_length() and frees their tables.';

